import{_ as i,l as n,o as e,c as l,v as t,p as s,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"红黑树直觉","description":"","frontmatter":{"title":"红黑树直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rbtree-intuition.md","filePath":"cs/rbtree-intuition.md","lastUpdated":1789023840000}'),p={name:"cs/rbtree-intuition.md"};function B(_,a,m,A,u,E){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="红黑树直觉" tabindex="-1">红黑树直觉 <a class="header-anchor" href="#红黑树直觉" aria-label="Permalink to &quot;红黑树直觉&quot;">​</a></h1><div class="epigraph"><p>用红黑两色约束路径上的黑高度，不必让每一层左右高度只差 1；旋转次数更稳，对数高度仍在。</p><footer>—— 据 Guibas and Sedgewick, A Dichromatic Framework for Balanced Trees, FOCS 1978；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/avl-rotate">上一课</a>用严格高度差和旋转把 \\(h\\) 钉在对数。实践中库常用更松的结构：插入最多常数次旋转。<a href="/cs/avl-rotate">二叉查找树</a>不变式仍要满足。本课不重讲 LL/RR 四种图。缺口是红黑直觉：颜色 + 黑高度，从而最坏仍 \\(\\Theta(\\log n)\\)，插入修复更局部。不把 CLRS 第 13 章每一种 case 抄成词条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AVL 每次插入都可能沿路径更新平衡因子并旋转，删除更甚。需要一种平衡，使「树不会退化成链」但允许左右高度差到常数倍。缺口不是新的键序，而是<strong>额外一比特颜色</strong>加上几条全局规则，推出最长路径不超过最短的两倍。</p><p>规则直觉：根黑；红节点的孩子黑（没有连续红）；任意节点到叶的黑节点数相同。叶可以是 NIL 黑哨兵。本课用这些推出高度界，不写完插入着色的全部分支。</p><p><span class="marginnote">2-3-4 树与红黑同构是常见对照：红边把 3、4 节点拆成二叉。本课点名，不把 B 树提前讲完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>黑高度 \\(bh\\)：从该点到叶的黑节点数（不含自身或含，须一致）。无连续红 ⇒ 红节点把路径拉长至多一倍 ⇒ \\(h\\le 2bh\\)。全黑路径最短，\\(n\\) 至少随 \\(bh\\) 指数涨 ⇒ \\(h=O(\\log n)\\)。</p><p>插入先当 BST 红叶挂上，再沿路径改色或旋转，消除红-红。旋转仍是上一课那一对。删除更繁，本课只承认存在 \\(\\Theta(\\log n)\\) 算法。</p>',10)),(e(),s(h,null,{default:r(()=>[c(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BST%5B%22BST%20%E6%8F%92%E5%85%A5%E4%B8%BA%E7%BA%A2%E5%8F%B6%22%5D%20--%3E%20FIX%5B%22%E6%94%B9%E8%89%B2%E6%88%96%E6%97%8B%E8%BD%AC%E6%B6%88%E7%BA%A2%E7%BA%A2%22%5D%0A%20%20FIX%20--%3E%20BH%5B%22%E9%BB%91%E9%AB%98%E5%BA%A6%E5%85%A8%E5%B1%80%E4%B8%80%E8%87%B4%22%5D%0A%20%20BH%20--%3E%20LOG%5B%22h%20%3D%20O(log%20n)%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>合同与 AVL 相同：有序字典最坏对数。差别在常数：红黑插入旋转 \\(O(1)\\) 次（另加 \\(O(\\log n)\\) 改色），AVL 更扁。语言标准库的 <code>map</code> 常选红黑，因为插入删除与查找折中。</p><p>颜色是表示的一部分，不是键。中序序列仍完全由 BST 不变式决定。改色不改变形状，旋转才改变高度；两者配合才恢复规则。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明插入全部 case 的正确性，不引入 AA 树、替罪羊树。伸展树用摊还、无额外平衡位，是另一合同。外存上二叉节点太瘦，下一课 B 树把扇出加大。</p><p>后课默认：内存有序字典可以当红黑用，最坏 \\(\\Theta(\\log n)\\)。磁盘上比较次数要按页算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>红黑用颜色约束黑高度，路径长至多差一倍，故对数高。</li><li>旋转原语与 AVL 相同；插入修复更局部。</li><li>外存需要高扇出，下一课 B 树。</li><li>本课不把插入全部着色 case 写成词条；合同已是最坏对数。</li><li>出处：Guibas and Sedgewick, <em>FOCS</em>, 1978；Cormen et al. 第 13 章。</li></ul>',8))])}const f=i(p,[["render",B]]);export{b as __pageData,f as default};
